#include <string>
#include <algorithm>
using namespace std;

class Solution {
public:
    string smallestString(string s) {
        string best = s;
        int n = s.size();
        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                string cand = s;
                reverse(cand.begin() + i, cand.begin() + j + 1);
                if (cand < best) {
                    best = cand;
                }
            }
        }
        return best;
    }
};

class Solution {
    public String smallestString(String s) {
        String best = s;
        int n = s.length();
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                char[] arr = s.toCharArray();
                int l = i, r = j;
                while (l < r) {
                    char t = arr[l]; arr[l] = arr[r]; arr[r] = t;
                    l++; r--;
                }
                String cand = new String(arr);
                if (cand.compareTo(best) < 0) {
                    best = cand;
                }
            }
        }
        return best;
    }
}

var smallestString = function(s) {
    let best = s;
    const n = s.length;
    for (let i = 0; i < n; i++) {
        for (let j = i + 1; j < n; j++) {
            const cand = s.slice(0, i) + s.slice(i, j + 1).split('').reverse().join('') + s.slice(j + 1);
            if (cand < best) {
                best = cand;
            }
        }
    }
    return best;
};
